create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text, timezone text default 'Asia/Kolkata', created_at timestamptz default now());
create table public.tasks (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, title text not null check(char_length(title) between 1 and 160), notes text, priority text not null default 'Medium' check(priority in ('High','Medium','Low')), estimated_minutes integer not null default 45 check(estimated_minutes between 5 and 720), due_at timestamptz, completed boolean not null default false, completed_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.focus_sessions (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, task_id uuid references public.tasks(id) on delete set null, duration_minutes integer not null check(duration_minutes between 1 and 480), completed boolean not null default false, started_at timestamptz not null default now(), ended_at timestamptz);
create table public.weekly_reviews (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, week_start date not null, wins text, blockers text, next_week_priority text, created_at timestamptz not null default now(), unique(user_id,week_start));
alter table public.profiles enable row level security; alter table public.tasks enable row level security; alter table public.focus_sessions enable row level security; alter table public.weekly_reviews enable row level security;
create policy "profiles own" on public.profiles for all using(auth.uid()=id) with check(auth.uid()=id); create policy "tasks own" on public.tasks for all using(auth.uid()=user_id) with check(auth.uid()=user_id); create policy "sessions own" on public.focus_sessions for all using(auth.uid()=user_id) with check(auth.uid()=user_id); create policy "reviews own" on public.weekly_reviews for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create or replace function public.create_profile_for_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,display_name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name','')) on conflict(id) do nothing; return new; end; $$; create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.create_profile_for_user();